entries[1223103] = { ["name"] = "Warbreaker", ["text"] = "Grants Colossus Smash and replaces it with Warbreaker . If you already know Warbreaker , instead increases its cooldown recovery rate by 100%.\n\nWarbreaker\n:\nSmash the ground and shatter the armor of all enemies within 10 yds, dealing (306.263% of Attack Power) Physical damage and increasing damage you deal to them by 30% for 10 sec." }
entries[1223104] = { ["name"] = "Sanguithorn", ["text"] = "5 yd range\n2.5 sec cast\nOnce only usable as an edible plant for fleeting magical power, recent evolutionary changes and alchemical breakthroughs with bloodthistle have led to its use across the professions. This more potent growth has come to be known as sanguithorn, and still boasts fearsome magical capabilities.\n\nSanguithorn are known to tether themselves to rocks, either above or under the ground, so check for them in more rugged terrain." }
entries[1223106] = { ["name"] = "Azeroot", ["text"] = "5 yd range\n2.5 sec cast\nThe hearty earthroot plant has grown stronger in recent years. Difficult to gather, but just as potent in crafting, azeroot is key to many recipes in Quel'Thalas.\n\nThis sturdy wooden herb can be found on or around trees in the Quel'Thalas region." }
